import { applyExactUnifiedDiff } from "./patch-pno-unified-v1.mjs";
import { FRONT_DIFF } from "./patch-pno-frontend-diff-v1.mjs";

const MARKER = "PNO_BROWSER_CACHE_V1";
function injectPnoRuntimeUi(source) {
  if (source.includes("PNO_RUNTIME_UI_BOOTSTRAP_V1")) return source;
  const helperAnchor = `document.addEventListener("DOMContentLoaded", () => {`;
  const helper = `// PNO_RUNTIME_UI_BOOTSTRAP_V1: staged DEV UI keeps canonical HTML/CSS untouched.\nfunction ensurePnoRuntimeUi() {\n  const dialog = el("pending-parcels-dialog");\n  if (dialog) {\n    const card = dialog.querySelector(".parcel-list-card");\n    const title = dialog.querySelector("h2");\n    if (title && !title.id) title.id = "pending-parcels-title";\n    const total = el("pending-parcels-total");\n    const toolbar = total?.closest(".parcel-list-toolbar");\n    if (toolbar && total && !el("pending-parcels-page")) {\n      const meta = document.createElement("div");\n      meta.className = "pno-modal-meta";\n      total.replaceWith(meta);\n      meta.append(total);\n      const page = document.createElement("span"); page.id = "pending-parcels-page"; page.textContent = "หน้า -";\n      const cache = document.createElement("span"); cache.id = "pending-parcels-cache"; cache.className = "pno-cache-state"; cache.textContent = "cache -";\n      meta.append(page, cache);\n    }\n    if (card && !el("pending-parcels-pager")) {\n      const pager = document.createElement("div"); pager.id = "pending-parcels-pager"; pager.className = "pno-pager hidden";\n      pager.innerHTML = '<button id="pending-parcels-prev" class="btn btn-header" type="button">← ก่อนหน้า</button><button id="pending-parcels-refresh" class="btn btn-header" type="button">รีเฟรชหน้านี้</button><button id="pending-parcels-next" class="btn btn-accent" type="button">ถัดไป →</button>';\n      card.append(pager);\n    }\n  }\n  if (!document.getElementById("pno-ultra-low-quota-style-v1")) {\n    const style = document.createElement("style");\n    style.id = "pno-ultra-low-quota-style-v1";\n    style.textContent = PNO_RUNTIME_CSS_V1;\n    document.head.append(style);\n  }\n}\nconst PNO_RUNTIME_CSS_V1 = "/* PNO_ULTRA_LOW_QUOTA_UI_V1: compact warehouse-entry truth + click-only lazy PNO. */\n.ms-page .expected-parcels-badge.pno-summary {\n  display: block;\n  width: 100%;\n  max-width: 460px;\n  margin-top: 8px;\n  padding: 8px;\n  border: 1px solid #d9ddd8;\n  border-radius: 10px;\n  background: #fff;\n  color: #171917;\n  font-size: 11px;\n  font-weight: 700;\n  white-space: normal;\n  box-sizing: border-box;\n}\n.ms-page .pno-metrics {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 5px;\n}\n.ms-page .pno-metrics > span,\n.ms-page .pno-metrics > button {\n  min-width: 0;\n  min-height: 46px;\n  padding: 6px 5px;\n  border: 1px solid #e0e3df;\n  border-radius: 8px;\n  background: #f7f8f6;\n  color: #202320;\n  text-align: center;\n  font: inherit;\n  cursor: default;\n}\n.ms-page .pno-metrics > button {\n  cursor: pointer;\n  background: #fffef4;\n  border-color: #d9c25b;\n}\n.ms-page .pno-metrics > button:hover { background: #fff7c9; }\n.ms-page .pno-metrics small { display: block; color: #6d736d; font-size: 9px; font-weight: 700; line-height: 1.15; }\n.ms-page .pno-metrics b { display: block; margin-top: 3px; color: #161816; font-size: 15px; line-height: 1; }\n.ms-page .pno-progress-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: 7px; }\n.ms-page .pno-progress-head strong { font-size: 14px; color: #171917; }\n.ms-page .pno-progress-head span { color: #6c726c; font-size: 9px; }\n.ms-page .pno-progress-track {\n  position: relative;\n  height: 9px;\n  margin-top: 4px;\n  overflow: hidden;\n  border-radius: 999px;\n  background: #eceeeb;\n}\n.ms-page .pno-progress-fill {\n  position: absolute;\n  inset: 0;\n  transform: scaleX(var(--pno-progress, 0));\n  transform-origin: left center;\n  border-radius: inherit;\n  background: #d7443e;\n  transition: transform 320ms ease;\n  overflow: hidden;\n}\n.ms-page .pno-summary.is-amber .pno-progress-fill { background: #d99a18; }\n.ms-page .pno-summary.is-green .pno-progress-fill { background: #75b47f; }\n.ms-page .pno-summary.is-complete .pno-progress-fill { background: #3d8d56; }\n.ms-page .pno-progress-fill::after {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: -35%;\n  width: 26%;\n  background: rgba(255,255,255,.38);\n  transform: skewX(-18deg);\n  animation: pno-progress-sheen 2.4s linear infinite;\n}\n.ms-page .pno-progress-marker {\n  position: absolute;\n  top: -2px;\n  bottom: -2px;\n  left: 90%;\n  width: 1px;\n  background: #535953;\n  opacity: .75;\n}\n@keyframes pno-progress-sheen {\n  from { transform: translateX(0) skewX(-18deg); }\n  to { transform: translateX(520%) skewX(-18deg); }\n}\n@media (prefers-reduced-motion: reduce) {\n  .ms-page .pno-progress-fill { transition: none; }\n  .ms-page .pno-progress-fill::after { animation: none; }\n}\n.ms-page .pno-summary.pno-warning { border-color: #e2b36f; background: #fff9ef; }\n.ms-page .pno-summary.pno-empty { border-color: #dfe2de; background: #f7f8f6; }\n.ms-page .pno-summary.pno-warning > strong,\n.ms-page .pno-summary.pno-empty > strong { display: block; color: #282b28; font-size: 11px; }\n.ms-page .pno-summary.pno-warning > span,\n.ms-page .pno-summary.pno-empty > span { display: block; margin-top: 2px; color: #707670; font-size: 9px; }\n.ms-page .pno-modal-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; }\n.ms-page .pno-modal-meta > span { padding: 3px 7px; border: 1px solid #dfe2de; border-radius: 999px; background: #f5f6f4; color: #555b55; font-size: 10px; }\n.ms-page .pno-cache-state { font-variant-numeric: tabular-nums; }\n.ms-page .pno-pager { display: flex; justify-content: flex-end; gap: 8px; margin-top: 10px; }\n.ms-page .pno-pager button:disabled { opacity: .45; cursor: not-allowed; }\n.ms-page .pno-source-warning { margin-bottom: 7px; padding: 7px 9px; border: 1px solid #e2b36f; border-radius: 8px; background: #fff9ef; color: #5b461f; font-size: 10px; }\n@media (max-width: 720px) {\n  .ms-page .expected-parcels-badge.pno-summary { max-width: none; margin-top: 8px; padding: 7px; font-size: 11px; }\n  .ms-page .pno-metrics > span,\n  .ms-page .pno-metrics > button { min-height: 43px; padding: 5px 3px; }\n  .ms-page .pno-metrics b { font-size: 14px; }\n  .ms-page .pno-pager { justify-content: stretch; }\n  .ms-page .pno-pager button { flex: 1 1 0; min-width: 0; }\n}\n";\n\n${helperAnchor}`;
  let output = source.replace(helperAnchor, helper);
  output = output.replace(helperAnchor, `${helperAnchor}\n  ensurePnoRuntimeUi();`);
  return output;
}

export function patchPnoUltraLowQuotaFrontend(source) {
  let output = String(source || "");
  if (!output.includes(MARKER)) output = applyExactUnifiedDiff(output, FRONT_DIFF, "frontend-core");
  return injectPnoRuntimeUi(output);
}
